from pathlib import Path

def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected one patch anchor, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

def main() -> None:
    replace_once(Path('insight_desk/pipeline/semantics.py'), '_ENGLISH_CHART_STREAK_RE = re.compile(r"\\b(\\d+)(?:st|nd|rd|th)\\s+week\\b", re.IGNORECASE)\n', '_ENGLISH_CHART_STREAK_RE = re.compile(r"\\b(\\d+)(?:st|nd|rd|th)\\s+week\\b", re.IGNORECASE)\n_ENGLISH_EXECUTIVE_ROLE = (\n    r"(?:chief\\s+(?:executive|financial|operating|technology|revenue|product|legal|"\n    r"marketing|commercial|strategy)\\s+officer|CEO|CFO|COO|CTO|CRO|CPO|CLO|CMO|"\n    r"president|chair(?:man|woman|person)?|general\\s+counsel)"\n)\n_ENGLISH_CORPORATE_REPLACEMENT_RE = re.compile(\n    rf"^(?P<subject>[A-Za-z0-9][A-Za-z0-9&.\'’\\- ]{{1,79}}?)\\s+"\n    rf"(?P<action>replaces?|replaced)\\s+(?:its\\s+|the\\s+)?"\n    rf"(?P<object>{_ENGLISH_EXECUTIVE_ROLE})"\n    r"(?:\\s+(?:after|following|amid)\\b.*)?$",\n    re.IGNORECASE,\n)\n_ENGLISH_CORPORATE_REPLACEMENT_UNSAFE_RE = re.compile(\n    r"\\b(?:may|might|could|would|will|reportedly|allegedly|rumou?red|"\n    r"plans?\\s+to|seeks?\\s+to|aims?\\s+to|expected\\s+to)\\s+replac(?:e|es|ed)\\b",\n    re.IGNORECASE,\n)\n_INDUSTRY_BARE_RELATION_RE = re.compile(\n    rf"^(?P<subject>[A-Za-z0-9가-힣·&\'’\\-]{{2,40}})\\s+"\n    rf"(?P<object>{_RELATION_OBJECT})\\s+"\n    r"(?P<action>착공식|착공|공급|수주|신설|출범|투자|지원)"\n    r"(?:을|를|에)?\\s*(?:했다|한다|됐다|된다|하기로\\s+했다|키로\\s+했다|"\n    r"예정이다|나섰다|시작했다|연다|열었다|들어갔다|확정했다)?$",\n    re.IGNORECASE,\n)\n_AFFILIATION_BARE_RELATION_RE = re.compile(\n    rf"^(?P<subject>{_RELATION_SUBJECT})\\s+"\n    r"(?P<object>(?:\\d+\\s*년\\s*만에\\s+)?(?:JYP|YG|SM|HYBE|하이브|소속사|기획사))"\n    r"(?:를|을)?\\s*(?P<action>떠난다|떠났다|결별|이적)(?:했다|한다|됐다|된다)?$",\n    re.IGNORECASE,\n)\n_ROSTER_CAUSE_OUTCOME_RELATION_RE = re.compile(\n    r"^(?:KBO\\s+)?(?:규정\\s+착오|행정\\s+착오|절차\\s+문제)(?:로|때문에)\\s+"\n    rf"(?P<subject>{_RELATION_SUBJECT})\\s+"\n    rf"(?P<object>{_RELATION_OBJECT})\\s+"\n    r"(?P<action>영입\\s*무산|영입\\s*확정|계약\\s*체결|방출|이적\\s*확정|트레이드\\s*성사)"\n    r"(?:됐다|되었다|했다|한다)?$",\n    re.IGNORECASE,\n)\n_UNCLASSIFIED_EVENT_SIGNAL_RE = re.compile(\n    r"(?:\\b(?:replaces?|replaced|appoints?|appointed|acquires?|acquired)\\b|"\n    r"(?:편입|편출|교체|선임|임명|공급|수주|신설|출범|인수)"\n    r"(?:했다|됐다|한다|된다)?(?=$|[\\s,，:;])|"\n    r"영입\\s*무산|계약\\s*체결|떠난다|떠났다)",\n    re.IGNORECASE,\n)\n_UNCLASSIFIED_EVENT_UNSAFE_RE = re.compile(\n    r"(?:가능성|전망|거론|검토|논의|분석|설명|주장|rumou?red|reportedly|"\n    r"\\bmay\\b|\\bmight\\b|\\bcould\\b|\\bwould\\b|\\bwill\\b|\\bplans?\\s+to\\b)",\n    re.IGNORECASE,\n)\n\n')
    replace_once(Path('insight_desk/pipeline/semantics.py'), '    if not clean or _RELATION_NON_EVENT_TAIL_RE.search(clean):\n        return None\n\n    regulation = _REGULATION_RELATION_RE.match(clean)\n', '    if not clean or _RELATION_NON_EVENT_TAIL_RE.search(clean):\n        return None\n\n    if not _ENGLISH_CORPORATE_REPLACEMENT_UNSAFE_RE.search(clean):\n        corporate_replacement = _ENGLISH_CORPORATE_REPLACEMENT_RE.match(clean)\n        if corporate_replacement is not None:\n            return _relation_fact("ANNOUNCEMENT", corporate_replacement, "교체")\n\n    regulation = _REGULATION_RELATION_RE.match(clean)\n')
    replace_once(Path('insight_desk/pipeline/semantics.py'), '    affiliation = _AFFILIATION_RELATION_RE.match(clean)\n    if affiliation is not None:\n        raw_action = affiliation.group("action")\n', '    affiliation = _AFFILIATION_RELATION_RE.match(clean) or _AFFILIATION_BARE_RELATION_RE.match(clean)\n    if affiliation is not None:\n        raw_action = affiliation.group("action")\n')
    replace_once(Path('insight_desk/pipeline/semantics.py'), '    roster = _ROSTER_OUTCOME_RELATION_RE.match(clean)\n    if roster is not None:\n', '    roster = _ROSTER_OUTCOME_RELATION_RE.match(clean) or _ROSTER_CAUSE_OUTCOME_RELATION_RE.match(clean)\n    if roster is not None:\n')
    replace_once(Path('insight_desk/pipeline/semantics.py'), '    industry = _INDUSTRY_RELATION_RE.match(clean)\n    if industry is not None:\n', '    industry = _INDUSTRY_RELATION_RE.match(clean) or _INDUSTRY_BARE_RELATION_RE.match(clean)\n    if industry is not None:\n')
    replace_once(Path('insight_desk/pipeline/semantics.py'), '\n\n@dataclass(frozen=True)\nclass CanonicalEvent:\n', '\n\ndef explicit_unclassified_event_signal(text: str) -> bool:\n    """Return a review-only signal for a concrete-looking unclassified event.\n\n    This helper never selects a story. It only prevents a zero-story run from\n    being declared safely empty when a directly phrased event predicate fell\n    outside the canonical parser. Uncertainty and question forms fail closed.\n    """\n\n    clean = normalize_text(text).strip(" .!?。！？")\n    if not clean or text.rstrip().endswith(("?", "？")):\n        return False\n    if typed_event_relation(clean) is not None:\n        return False\n    if _RELATION_NON_EVENT_TAIL_RE.search(clean) or _UNCLASSIFIED_EVENT_UNSAFE_RE.search(clean):\n        return False\n    return bool(_UNCLASSIFIED_EVENT_SIGNAL_RE.search(clean))\n\n\n@dataclass(frozen=True)\nclass CanonicalEvent:\n')
    replace_once(Path('insight_desk/pipeline/selection.py'), '    metric_summary_preserves_entity_binding,\n    same_event_lifecycle,\n    summary_preserves_primary_focus,\n)\n', '    explicit_unclassified_event_signal,\n    metric_summary_preserves_entity_binding,\n    same_event_lifecycle,\n    summary_preserves_primary_focus,\n)\n')
    replace_once(Path('insight_desk/pipeline/selection.py'), 'def _is_strong_rejected(assessment: EditorialAssessment) -> bool:\n', 'def _is_unclassified_event_recall_risk(\n    cluster: StoryCluster,\n    assessment: EditorialAssessment,\n    *,\n    novelty: str,\n    freshness_reasons: tuple[str, ...],\n) -> bool:\n    """Expose a concrete OTHER event to diagnostics without selecting it."""\n\n    if (\n        not assessment.relevance.passed\n        or assessment.event.event_type != "OTHER"\n        or novelty == "UNCHANGED"\n        or freshness_reasons\n        or assessment.evidence.conflict_state not in {"NO_CONFLICT", "CONFIRMED_MATCH"}\n    ):\n        return False\n    title = effective_title(best_headline_item(cluster.items))\n    return explicit_unclassified_event_signal(title)\n\n\ndef _is_strong_rejected(assessment: EditorialAssessment) -> bool:\n')
    replace_once(Path('insight_desk/pipeline/selection.py'), '        if _is_strong_rejected(assessment):\n            strong_rejected_candidates += 1\n            funnel[topic.id]["strong_rejected"] += 1\n            enrichment_candidates.append(cluster)\n        elif (\n', '        if _is_unclassified_event_recall_risk(\n            cluster,\n            assessment,\n            novelty=novelty,\n            freshness_reasons=freshness_reasons,\n        ) or _is_strong_rejected(assessment):\n            strong_rejected_candidates += 1\n            funnel[topic.id]["strong_rejected"] += 1\n            enrichment_candidates.append(cluster)\n        elif (\n')
    Path('tests/test_run99_false_empty_recall.py').write_text('from __future__ import annotations\n\nimport json\nimport unittest\nfrom datetime import datetime\nfrom pathlib import Path\n\nfrom insight_desk.config import load_topics\nfrom insight_desk.domain.models import EvidenceType, NewsItem\nfrom insight_desk.pipeline.clustering import StoryCluster\nfrom insight_desk.pipeline.selection import select_clusters\nfrom insight_desk.pipeline.semantics import (\n    explicit_unclassified_event_signal,\n    typed_event_relation,\n)\n\n\nFIXTURE = Path(__file__).with_name("fixtures") / "run96_targeted_recall.json"\n\n\ndef _item(\n    *,\n    evidence_id: str,\n    topic_id: str,\n    query: str,\n    title: str,\n    lead: str = "",\n    publisher: str = "fixture.test",\n) -> NewsItem:\n    return NewsItem(\n        evidence_id=evidence_id,\n        topic_id=topic_id,\n        query=query,\n        title=title,\n        summary=lead,\n        original_url=f"https://fixture.test/{evidence_id}",\n        naver_url="",\n        canonical_url=f"https://fixture.test/{evidence_id}",\n        published_at="2026-08-14T06:30:00+09:00",\n        source_domain="fixture.test",\n        content_hash=evidence_id,\n        score=90.0,\n        metadata_title=title,\n        metadata_description=lead,\n        publisher=publisher,\n        provenance=(EvidenceType.SEARCH_SNIPPET, EvidenceType.ENRICHED_METADATA),\n        matched_topic_ids=(topic_id,),\n        retrieval_channels=("SIM",),\n        retrieval_queries=(query,),\n    )\n\n\nclass Run99FalseEmptyRecallTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls) -> None:\n        cls.topics, _ = load_topics(Path("config/topics.json"))\n\n    def test_openai_executive_replacement_is_a_bound_relation(self) -> None:\n        relation = typed_event_relation(\n            "OpenAI replaces chief revenue officer after just months"\n        )\n        self.assertIsNotNone(relation)\n        assert relation is not None\n        event_type, fact = relation\n        self.assertEqual(event_type, "ANNOUNCEMENT")\n        self.assertEqual(fact.subject, "OpenAI")\n        self.assertEqual(fact.object.casefold(), "chief revenue officer")\n        self.assertEqual(fact.relation, "교체")\n\n    def test_openai_replacement_does_not_admit_prospective_or_non_personnel_uses(self) -> None:\n        negatives = (\n            "OpenAI may replace chief revenue officer",\n            "OpenAI could replace chief revenue officer",\n            "OpenAI will replace chief revenue officer",\n            "OpenAI plans to replace chief revenue officer",\n            "Who could replace the CEO at OpenAI?",\n            "CEO discusses replacing workers with AI",\n            "Replacement demand for GPUs rises",\n        )\n        for title in negatives:\n            self.assertIsNone(typed_event_relation(title), title)\n\n    def test_run96_relation_families_accept_run99_surface_variants(self) -> None:\n        cases = (\n            (\n                "삼성SDS 중앙부처 9곳에 AI 협업 솔루션 공급",\n                "INDUSTRY_CHANGE",\n                "공급",\n            ),\n            (\n                "트와이스 채영 14년 만에 JYP 떠난다",\n                "ANNOUNCEMENT",\n                "떠남",\n            ),\n            (\n                "KBO 규정 착오로 LG 오카다 영입 무산",\n                "ROSTER_PERSONNEL",\n                "영입 무산",\n            ),\n        )\n        for title, event_type, action in cases:\n            relation = typed_event_relation(title)\n            self.assertIsNotNone(relation, title)\n            assert relation is not None\n            self.assertEqual(relation[0], event_type, title)\n            self.assertEqual(relation[1].relation, action, title)\n\n    def test_locked_run96_true_negatives_stay_closed(self) -> None:\n        payload = json.loads(FIXTURE.read_text(encoding="utf-8"))\n        negatives = payload["true_negative_titles"]\n        self.assertEqual(len(negatives), 44)\n        for title in negatives:\n            self.assertIsNone(typed_event_relation(title), title)\n\n    def test_unclassified_signal_is_diagnostic_only_and_uncertainty_safe(self) -> None:\n        self.assertTrue(\n            explicit_unclassified_event_signal(\n                "코스피 MSCI 정기변경, 에코프로머티 등 4개 종목 편입"\n            )\n        )\n        negatives = (\n            "MSCI 편입 가능성 전망",\n            "MSCI 편입 검토",\n            "Who could replace the CEO at OpenAI?",\n            "AI 공급 전망",\n            "GPU 공급 부족 분석",\n        )\n        for title in negatives:\n            self.assertFalse(explicit_unclassified_event_signal(title), title)\n\n    def test_unclassified_current_event_prevents_false_valid_empty(self) -> None:\n        item = _item(\n            evidence_id="run99-shadow-openai-acquisition",\n            topic_id="ai_tech",\n            query="OpenAI",\n            title="OpenAI acquires startup in infrastructure deal",\n            lead="OpenAI acquired the startup to expand its infrastructure operations.",\n        )\n        result = select_clusters(\n            (StoryCluster("ai_tech", (item,)),),\n            self.topics,\n            limit=10,\n            now=datetime.fromisoformat("2026-08-14T07:30:00+09:00"),\n        )\n        self.assertEqual(result.selected, ())\n        self.assertEqual(result.strong_rejected_candidates, 1)\n        self.assertTrue(result.filter_collapse)\n        self.assertEqual(result.funnel["ai_tech"]["strong_rejected"], 1)\n\n    def test_run99_openai_candidate_can_reach_selection(self) -> None:\n        item = _item(\n            evidence_id="run99-openai-cro",\n            topic_id="ai_tech",\n            query="OpenAI",\n            title="OpenAI replaces chief revenue officer after just months",\n            lead=(\n                "OpenAI said Denise Dresser is leaving the chief revenue officer role "\n                "after just months in the job."\n            ),\n            publisher="The New York Times",\n        )\n        result = select_clusters(\n            (StoryCluster("ai_tech", (item,)),),\n            self.topics,\n            limit=10,\n            now=datetime.fromisoformat("2026-08-14T07:30:00+09:00"),\n        )\n        self.assertEqual(len(result.selected), 1, result.audit)\n        self.assertEqual(result.strong_rejected_candidates, 0)\n        row = result.audit[0]\n        self.assertTrue(row["qualifying"])\n        self.assertEqual(row["event_type"], "ANNOUNCEMENT")\n\n\nif __name__ == "__main__":\n    unittest.main()\n', encoding='utf-8')

if __name__ == '__main__':
    main()
